function playNewGameChiptune(){try{const C=window.AudioContext||(window as typeof window & {webkitAudioContext?:typeof AudioContext}).webkitAudioContext;if(!C)return;const audio=new C();void audio.resume();const start=audio.currentTime;const rise=1.45;const hold=1.65;const release=.32;const end=start+rise+hold+release;const master=audio.createGain();master.gain.setValueAtTime(.0001,start);master.gain.linearRampToValueAtTime(.46,start+rise);master.gain.setValueAtTime(.46,start+rise+hold);master.gain.exponentialRampToValueAtTime(.0001,end);master.connect(audio.destination);const chord=[220,261.63,329.63,392];chord.forEach((hz,index)=>{const oscillator=audio.createOscillator();const gain=audio.createGain();oscillator.type='square';oscillator.frequency.setValueAtTime(hz*.62,start);oscillator.frequency.exponentialRampToValueAtTime(hz,start+rise);gain.gain.setValueAtTime([.11,.085,.065,.05][index],start);oscillator.connect(gain);gain.connect(master);oscillator.start(start);oscillator.stop(start+rise+hold);});const cNote=audio.createOscillator();const cGain=audio.createGain();const noteAt=start+rise+hold;cNote.type='square';cNote.frequency.setValueAtTime(261.63,noteAt);cGain.gain.setValueAtTime(.14,noteAt);cGain.gain.exponentialRampToValueAtTime(.0001,noteAt+.18);cNote.connect(cGain);cGain.connect(master);cNote.start(noteAt);cNote.stop(noteAt+.2);window.setTimeout(()=>void audio.close(),Math.ceil((rise+hold+release+.25)*1000));}catch(error){console.warn('No se pudo reproducir el sonido de nueva partida:',error);}}
