function gearSlot(item:WorldState['player']['inventory'][number]){const label=gearLabel(item);return /casco|gorra|sombrero|capucha/.test(label)?'head':/pantal[oó]n|pantalon/.test(label)?'legs':/guantes|guante/.test(label)?'hands':/botas|bota|calzado|zapato/.test(label)?'feet':/mascarilla|respirador|protector|armadura/.test(label)?'protection':'torso';}
function paintCharacterEquipment(){const root=document.getElementById('character-equipment-content');if(!root)return;const items=state.player.inventory.filter(i=>i.quantity>0);const wearables=items.filter(isWearable);const weapons=items.filter(isWeapon);const tools=items.filter(i=>i.kind==='tool'&&!i.equippedAsWeapon);const slots:[string,string][]=[['head','CABEZA'],['torso','TORSO'],['hands','MANOS'],['legs','PIERNAS'],['feet','PIES'],['protection','PROTECCIÓN']];const slotMarkup=slots.map(([slot,label])=>{const item=wearables.find(i=>i.equipped&&gearSlot(i)===slot);return `<div class="character-gear-slot ${item?'is-equipped':''}"><span class="gear-slot-symbol">${({'head':'◉','torso':'▤','hands':'⌁','legs':'╫','feet':'⌂','protection':'⬡'} as Record<string,string>)[slot]}</span><div><small>${label}</small><strong>${escapeHtml(item?.name??'Sin equipar')}</strong><span>${item?'INTEGRIDAD '+Math.round(item.integrity??item.condition??100)+'%':'Ranura libre'}</span></div>${item?`<button type="button" data-gear-remove="${escapeHtml(item.id)}">QUITAR</button>`:''}</div>`;}).join('');const weaponMarkup=weapons.length?weapons.map(i=>`<button type="button" class="character-item-choice ${i.equipped?'selected':''}" data-gear-equip="${escapeHtml(i.id)}"><span class="gear-item-glyph">${/pistola|rifle|escopeta|rev[oó]lver|arma de fuego/i.test(gearLabel(i))?'⌁':'†'}</span><span><strong>${escapeHtml(i.name)}</strong><small>${escapeHtml(i.description||'Arma disponible')} · ${i.quantity} en inventario</small></span><b>${i.equipped?'EQUIPADA':'EQUIPAR'}</b></button>`).join(''):'<p class="character-gear-empty">No llevás armas identificadas. Las que consigas aparecerán acá.</p>';const clothingMarkup=wearables.length?wearables.map(i=>`<button type="button" class="character-item-choice ${i.equipped?'selected':''}" data-gear-equip="${escapeHtml(i.id)}"><span class="gear-item-glyph">▤</span><span><strong>${escapeHtml(i.name)}</strong><small>${escapeHtml(i.description||'Prenda disponible')} · ESTADO ${Math.round(i.integrity??i.condition??100)}%</small></span><b>${i.equipped?'EQUIPADA':'EQUIPAR'}</b></button>`).join(''):'<p class="character-gear-empty">No hay prendas separadas en el inventario. La ropa básica del personaje no ocupa una ranura.</p>';root.innerHTML=`<section class="character-gear-section"><div class="character-section-heading"><h3>VESTIMENTA Y PROTECCIÓN</h3><span>${wearables.filter(i=>i.equipped).length} RANURAS OCUPADAS</span></div><div class="character-gear-slots">${slotMarkup}</div><div class="character-owned-list">${clothingMarkup}</div></section><section class="character-gear-section weapons-section" data-gear-destination="hand"><div class="character-section-heading"><h3>EN MANO</h3><span>${tools.some(i=>i.equipped)?'HERRAMIENTA LISTA':'MANO LIBRE'}</span></div><p class="character-section-note">Elegí una herramienta para llevarla en la mano. Solo podés llevar una a la vez.</p><div class="character-owned-list">${tools.length?tools.map(i=>`<button type="button" class="character-item-choice ${i.equipped?'selected':''}" data-gear-equip="${escapeHtml(i.id)}"><span class="gear-item-glyph">⌁</span><span><strong>${escapeHtml(i.name)}</strong><small>${escapeHtml(i.description||'Herramienta disponible')} · ${i.quantity} en inventario</small></span><b>${i.equipped?'EN MANO':'LLEVAR'}</b></button>`).join(''):'<p class="character-gear-empty">No llevás herramientas.</p>'}</div></section><section class="character-gear-section weapons-section" data-gear-destination="arsenal"><div class="character-section-heading"><h3>ARSENAL</h3><span>${weapons.filter(i=>i.equipped).length} EQUIPADAS</span></div><p class="character-section-note">Elegí un arma de tu inventario. Equipar otra reemplaza la anterior.</p><div class="character-owned-list">${weaponMarkup}</div></section>`;}
function openCharacterEquipment(){paintCharacterEquipment();$('character-equipment-modal').hidden=false;$('open-character-equipment').classList.add('window-open');}
function closeCharacterEquipment(){$('character-equipment-modal').hidden=true;$('open-character-equipment').classList.remove('window-open');}
$('open-character-equipment').addEventListener('click',()=>{if(!$('character-equipment-modal').hidden)closeCharacterEquipment();else openCharacterEquipment();});$('close-character-equipment').addEventListener('click',closeCharacterEquipment);$('character-equipment-modal').addEventListener('click',event=>{if(event.target===$('character-equipment-modal'))closeCharacterEquipment();});
// Header drag with left button; resize by right-button dragging from any panel corner.
type PanelGesture={panel:HTMLElement;mode:'move'|'resize';corner:string;startX:number;startY:number;left:number;top:number;width:number;height:number};
let panelGesture:PanelGesture|null=null;
// Disable Chromium's native right-click menu throughout the game; game-specific context actions still receive the event.
document.addEventListener('contextmenu',event=>{event.preventDefault();},true);
document.addEventListener('pointerdown',event=>{const e=event as PointerEvent;const target=e.target as HTMLElement;const panel=target.closest<HTMLElement>('.character-equipment-panel, .inventory-popup');if(!panel||e.button!==0&&e.button!==2)return;const rect=panel.getBoundingClientRect();const x=e.clientX-rect.left,y=e.clientY-rect.top,edge=40;const horizontal=x<edge?'left':x>rect.width-edge?'right':'';const vertical=y<edge?'top':y>rect.height-edge?'bottom':'';const corner=horizontal&&vertical?vertical+'-'+horizontal:'';
if(e.button===2){e.preventDefault();e.stopPropagation();panel.style.setProperty('transform','none','important');panel.style.setProperty('box-sizing','border-box','important');panel.style.setProperty('max-width','none','important');panel.style.setProperty('max-height','none','important');const resizeCorner=corner||((x<rect.width/2?'left':'right')+'-'+(y<rect.height/2?'top':'bottom'));panelGesture={panel,mode:'resize',corner:resizeCorner,startX:e.clientX,startY:e.clientY,left:rect.left,top:rect.top,width:rect.width,height:rect.height};panel.style.setProperty('left',rect.left+'px','important');panel.style.setProperty('top',rect.top+'px','important');panel.style.setProperty('right','auto','important');panel.style.setProperty('bottom','auto','important');return;}
const handle=target.closest<HTMLElement>('.character-equipment-header, .inventory-popup-heading');if(!handle||target.closest('button,input,select,textarea,a'))return;panel.style.setProperty('transform','none','important');panel.style.setProperty('box-sizing','border-box','important');panel.style.setProperty('max-width','none','important');panel.style.setProperty('max-height','none','important');panelGesture={panel,mode:'move',corner:'',startX:e.clientX,startY:e.clientY,left:rect.left,top:rect.top,width:rect.width,height:rect.height};panel.style.setProperty('left',rect.left+'px','important');panel.style.setProperty('top',rect.top+'px','important');panel.style.setProperty('right','auto','important');panel.style.setProperty('bottom','auto','important');e.preventDefault();});
document.addEventListener('pointermove',event=>{if(!panelGesture)return;const e=event as PointerEvent,g=panelGesture,dx=e.clientX-g.startX,dy=e.clientY-g.startY;if(g.mode==='move'){g.panel.style.setProperty('left',Math.max(0,Math.min(window.innerWidth-Math.min(100,g.width),g.left+dx))+'px','important');g.panel.style.setProperty('top',Math.max(0,Math.min(window.innerHeight-Math.min(48,g.height),g.top+dy))+'px','important');return;}const minW=260,minH=220;let left=g.left,top=g.top,width=g.width,height=g.height;if(g.corner.includes('right'))width=Math.max(minW,Math.min(window.innerWidth-g.left,g.width+dx));if(g.corner.includes('bottom'))height=Math.max(minH,Math.min(window.innerHeight-g.top,g.height+dy));if(g.corner.includes('left')){width=Math.max(minW,Math.min(g.width+g.left,g.width-dx));left=g.left+g.width-width;}if(g.corner.includes('top')){height=Math.max(minH,Math.min(g.height+g.top,g.height-dy));top=g.top+g.height-height;}g.panel.style.setProperty('left',left+'px','important');g.panel.style.setProperty('top',top+'px','important');g.panel.style.setProperty('right','auto','important');g.panel.style.setProperty('bottom','auto','important');g.panel.style.setProperty('width',width+'px','important');g.panel.style.setProperty('height',height+'px','important');},true);
document.addEventListener('pointerup',()=>{panelGesture=null});document.addEventListener('pointercancel',()=>{panelGesture=null});
document.addEventListener('click',event=>{const target=event.target as HTMLElement;if(target.closest('#close-character-equipment'))closeCharacterEquipment();if(target.closest('#inventory-close'))setInventoryOpen(false);});
$('character-equipment-content').addEventListener('click',event=>{const target=event.target as HTMLElement;const equip=target.closest<HTMLButtonElement>('[data-gear-equip]');const remove=target.closest<HTMLButtonElement>('[data-gear-remove]');const id=equip?.dataset.gearEquip??remove?.dataset.gearRemove;if(!id)return;const item=state.player.inventory.find(i=>i.id===id);if(!item)return;if(item.equipped){item.equipped=false;}else if(isWearable(item)){const slot=gearSlot(item);for(const other of state.player.inventory){if(other!==item&&other.equipped&&isWearable(other)&&gearSlot(other)===slot)other.equipped=false;}item.equipped=true;}else if(isWeapon(item)){for(const other of state.player.inventory){if(other!==item&&other.equipped&&isWeapon(other))other.equipped=false;}item.equipped=true;}render();paintCharacterEquipment();});

window.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('character-equipment-modal').hidden)closeCharacterEquipment();else if(event.key==='Escape'&&!$('inventory-popup').hidden)setInventoryOpen(false);});
$("inventory").addEventListener("click",event=>{const wearButton=(event.target as HTMLElement).closest<HTMLButtonElement>("[data-equip-clothing]");if(wearButton){const item=state.player.inventory.find(i=>i.id===wearButton.dataset.equipClothing);if(!item)return;const label=(item.name+' '+item.id+' '+item.description).toLocaleLowerCase('es');const slot=/casco|gorra|sombrero|capucha/.test(label)?'head':/pantal[oó]n|pantalon/.test(label)?'legs':/guantes|guante/.test(label)?'hands':/botas|bota|calzado|zapato/.test(label)?'feet':/mascarilla|respirador|protector|armadura/.test(label)?'protection':'torso';const isClothing=item.kind==='protective'||/ropa|vestimenta|campera|chaqueta|abrigo|pantal[oó]n|botas|guantes|casco|chaleco|mascarilla|uniforme|prenda|impermeable/.test(label);if(!isClothing)return;if(item.equipped)item.equipped=false;else{for(const other of state.player.inventory){const otherLabel=(other.name+' '+other.id+' '+other.description).toLocaleLowerCase('es');const otherSlot=/casco|gorra|sombrero|capucha/.test(otherLabel)?'head':/pantal[oó]n|pantalon/.test(otherLabel)?'legs':/guantes|guante/.test(otherLabel)?'hands':/botas|bota|calzado|zapato/.test(otherLabel)?'feet':/mascarilla|respirador|protector|armadura/.test(otherLabel)?'protection':'torso';if(other!==item&&other.equipped&&(other.kind==='protective'||/ropa|vestimenta|campera|chaqueta|abrigo|pantal[oó]n|botas|guantes|casco|chaleco|mascarilla|uniforme|prenda|impermeable/.test(otherLabel))&&otherSlot===slot)other.equipped=false;}item.equipped=true;}render();return;}const button=(event.target as HTMLElement).closest<HTMLButtonElement>(".use-inventory-item");if(!button)return;useItem(state,button.dataset.item);render();});
$("pause-game").addEventListener("click",()=>{formatClock(state);state.paused=!state.paused;if(state.paused&&walkingTimer!==null){clearInterval(walkingTimer);walkingTimer=null;}state.lastClockUpdate=Date.now();render();});
initConversationFolders();
$('quest-list').addEventListener('click',event=>{const target=event.target as HTMLElement;const button=target.closest<HTMLButtonElement>('[data-report-quest]');if(!button)return;const quest=state.quests.find(q=>q.id===button.dataset.reportQuest);const giver=quest?state.actors.find(a=>a.id===quest.giverId):undefined;if(!quest||!giver||quest.status!=='accepted'||quest.progress<1)return;state.selectedActorId=giver.id;if(Math.hypot(state.player.x-giver.x,state.player.y-giver.y)>2){state.log.push({tick:state.tick,text:'El objetivo está cumplido. Acércate a '+giver.name+' para informar y cerrar el encargo.',kind:'warning'});render();return;}talk(state,'Te informo: ya terminé el encargo.');render();});
document.querySelectorAll<HTMLElement>('[data-sleep-cancel]').forEach(el=>el.addEventListener('click',closeSleepModal));window.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('sleep-modal').hidden)closeSleepModal();});document.querySelector('[data-sleep-confirm]')?.addEventListener('click',()=>{if(state.paused)return;const hours=Number($<HTMLSelectElement>('sleep-hours').value)||8;closeSleepModal();sleep(state,hours);fatigueNoticeShown=false;document.querySelector('#fatigue-popup')!.setAttribute('hidden','');render();});
window.setInterval(()=>{if(!state.paused)advanceWorld(state);render();},30000);
document.getElementById("fatigue-dismiss")?.addEventListener("click",()=>{document.getElementById("fatigue-popup")!.hidden=true;});
window.setInterval(()=>{const now=Date.now();if(state.paused||!state.running){state.lastClockUpdate=now;return;}const last=state.lastClockUpdate??now;if(now-last>=30000){const elapsed=Math.floor((now-last)/30000);state.lastClockUpdate=last+elapsed*30000;for(let i=0;i<Math.min(elapsed,120);i++)advanceWorld(state);render();try{localStorage.setItem(SAVE_STORAGE_KEY,encodeSave(state));}catch{}}},1000);
const dialogueFeedForScroll=document.getElementById('dialogue-feed');
const dialogueJumpButton=document.getElementById('dialogue-jump-bottom');
const dialogueDistanceFromBottom=()=>dialogueFeedForScroll?dialogueFeedForScroll.scrollHeight-dialogueFeedForScroll.scrollTop-dialogueFeedForScroll.clientHeight:0;
const updateDialogueJumpButton=()=>{if(!dialogueFeedForScroll||!dialogueJumpButton)return;const distance=dialogueDistanceFromBottom();dialogueJumpButton.hidden=distance<32;};
dialogueFeedForScroll?.addEventListener('scroll',updateDialogueJumpButton,{passive:true});
dialogueJumpButton?.addEventListener('click',()=>{if(!dialogueFeedForScroll)return;dialogueFeedForScroll.scrollTo({top:dialogueFeedForScroll.scrollHeight,behavior:'smooth'});});
if(dialogueFeedForScroll){const dialogueObserver=new MutationObserver(()=>requestAnimationFrame(updateDialogueJumpButton));dialogueObserver.observe(dialogueFeedForScroll,{childList:true,subtree:true,characterData:true});updateDialogueJumpButton();}
render();
// Ensure the initial HUD is painted after the page and saved state are ready;
// opening a popup must not be the first action that refreshes character/progression.
requestAnimationFrame(()=>render());

function showDeleteQuestConfirmation(id:string){
 const quest=state.quests.find(q=>q.id===id);if(!quest)return;
 let modal=document.getElementById('delete-quest-confirm') as HTMLDivElement|null;
 if(!modal){
  modal=document.createElement('div');modal.id='delete-quest-confirm';modal.className='delete-quest-confirm-backdrop';modal.hidden=true;
  modal.innerHTML='<section class="delete-quest-confirm-panel" role="alertdialog" aria-modal="true"><p class="section-label">CONFIRMACIÓN REQUERIDA</p><h2>¿Seguro quiere borrar encargo?</h2><p class="delete-quest-name"></p><div class="delete-quest-actions"><button type="button" data-cancel-delete>Cancelar</button><button type="button" data-confirm-delete>Eliminar encargo</button></div></section>';
  document.body.append(modal);
  modal.addEventListener('click',event=>{const target=event.target as HTMLElement;if(target===modal||target.closest('[data-cancel-delete]')){modal!.hidden=true;return;}if(target.closest('[data-confirm-delete]')){const questId=modal!.dataset.questId;state.quests=state.quests.filter(q=>q.id!==questId);try{localStorage.setItem(SAVE_STORAGE_KEY,encodeSave(state));}catch(error){console.error('No se pudo guardar el diario:',error);}modal!.hidden=true;render();}});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal!.hidden)modal!.hidden=true;});
 }
 modal.dataset.questId=id;modal.querySelector<HTMLElement>('.delete-quest-name')!.textContent=quest.title;modal.hidden=false;
}
window.addEventListener('click',event=>{const rawTarget=event.target;const target=rawTarget instanceof Element?rawTarget:null;const button=target?.closest<HTMLButtonElement>('#quest-list [data-delete-quest]');if(!button)return;event.preventDefault();event.stopPropagation();showDeleteQuestConfirmation(button.getAttribute('data-delete-quest')||'');},true);
